def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context.get('supply', 0.0))
    day = int(day_context.get('day', 0))

    hp = float(my_status.get('hp', 0))
    budget = float(my_status.get('budget', 0))

    alive_opponents = []
    for opp_id, opp in opponents_status.items():
        try:
            if opp.get('alive', False):
                alive_opponents.append(opp)
        except Exception:
            continue

    if budget <= 0:
        return 0.0

    # Gather yesterday bids from immediate previous_trace only
    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {}) or {}
        b = prev.get('bid', None)
        if b is not None:
            try:
                yesterday_bids.append(float(b))
            except Exception:
                pass

    # Estimate clearing pressure
    if yesterday_bids:
        highest_prev_bid = max(yesterday_bids)
        second_prev_bid = sorted(yesterday_bids)[-2] if len(yesterday_bids) >= 2 else highest_prev_bid
    else:
        highest_prev_bid = 0.0
        second_prev_bid = 0.0

    # Determine urgency based on my HP and no_water_days if present
    no_water_days = float(my_status.get('no_water_days', 0))

    # Base bid target: aim just above likely clearing bid
    # If yesterday pressure was high, we must bid higher; otherwise bid around mid-range.
    high_pressure = highest_prev_bid >= (DAILY_SALARY * 0.85)

    # Supply-aware scaling: when supply is tight, bid more aggressively.
    # supply range is [15,25], so normalize.
    if MAX_SUPPLY > MIN_SUPPLY:
        supply_norm = (supply - MIN_SUPPLY) / (MAX_SUPPLY - MIN_SUPPLY)
    else:
        supply_norm = 0.5
    supply_norm = max(0.0, min(1.0, float(supply_norm)))
    tightness = 1.0 - supply_norm  # 1 when tight (15), 0 when abundant (25)

    # Compute candidate bid
    if high_pressure:
        # Bid slightly above the second-highest to steal allocation while controlling cost.
        target = max(second_prev_bid + 2.0, DAILY_SALARY * 0.75)
        # Tight supply increases target
        target *= (1.0 + 0.15 * tightness)
    else:
        # Moderate pressure: bid around a fraction of salary, adjusted by tightness.
        target = max(DAILY_SALARY * 0.45, second_prev_bid * 0.75)
        target *= (1.0 + 0.10 * tightness)

    # Urgency adjustments
    if hp <= 2.0:
        target *= 1.25
    elif hp <= 4.0:
        target *= 1.10

    if no_water_days >= 2.0:
        target *= 1.15

    # Cap by budget and keep within reasonable bounds
    target = float(target)
    if target > budget:
        target = budget

    # Avoid too-low bids when we can afford a meaningful amount
    min_reasonable = min(budget, DAILY_SALARY * (0.35 if not high_pressure else 0.65))
    if target < min_reasonable:
        target = min_reasonable

    # Final clamp
    if target < 0.0:
        target = 0.0
    return float(target)

