        if scarcity == 2:
            base = max(base, 88.0)
        return float(min(budget, base))

    if my_urgency == 2:
        if scarcity == 2:
            base = max(64.0, avg_prev + 2.0)
        elif scarcity == 1:
            base = max(48.0, avg_prev * 0.7 + 4.0)
        else:
            base = max(34.0, avg_prev * 0.45 + 2.0)
        return float(min(budget, base))

    if scarcity == 2:
        if rich_opponents >= 2:
