def get_bid(day_context, my_status, opponents_status):
    import random
    WATER_REQ = 8
    DAILY_SALARY = 140
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']
    alive_opponents = {oid: o for oid, o in opponents_status.items() if o['alive']}
    if not alive_opponents:
        return min(budget, DAILY_SALARY * 0.4 + random.uniform(0, 5))
    # Gather previous bids from alive opponents
    prev_bids = []
    for o in alive_opponents.values():
        trace = o.get('previous_trace')
        if trace and trace.get('bid') is not None:
            prev_bids.append(trace['bid'])
    # Determine a benchmark bid from opponents' yesterday's max
    if prev_bids:
        max_prev_bid = max(prev_bids)
        # If yesterday's max was very high, lower our bid to avoid overpaying (unless desperate)
        if max_prev_bid >= 0.85 * DAILY_SALARY:
            base = DAILY_SALARY * 0.5 if hp > 3 else DAILY_SALARY * 0.9
        else:
            base = max(DAILY_SALARY * 0.4, min(DAILY_SALARY * 0.75, max_prev_bid + 1))
    else:
        base = DAILY_SALARY * 0.55
    # Adjust based on dehydration
    if no_water_days > 0:
        base = max(base, DAILY_SALARY * 0.85)
    if hp <= 2:
        base = max(base, DAILY_SALARY * 0.9)
    # Ensure we don't exceed budget or salary
    bid = min(budget, base + random.uniform(0, 3))
    return bid
